      "proposed_laureates": [
        "Eli Yablonovitch",
        "John D. Joannopoulos",
        "Sajeev John"
      ],
      "assessment": {
        "nobel_worthiness": "Photonic crystals made the propagation and emission of light engineerable through band structure, creating a broad and durable field with applications across optics and photonics. The conceptual insight is fundamental as well as practical.",
        "attribution": "The three credited researchers represent complementary foundational theoretical and experimental contributions. The precise division of priority across early proposals and demonstrations should be examined closely.",
        "maturity": "The band-gap physics is well established and has been developed and applied for decades across many platforms.",
        "uncertainties": [
          "The candidate description groups several foundational steps; the committee should verify that the selected credit captures the distinct contributions behind the field's origin."
        ]
      }
    },
